        { id: "l168t4", type: "choice", q: "В орграфе есть дуга A -> B. Можно ли пройти из B в A по этой дуге?", options: ["да, всегда", "нет, только по направлению стрелки", "да, если граф связный", "да, если у вершины A степень больше"], answer: 1, explain: "Дуга проходится только в направлении стрелки." },
        { id: "l168t5", type: "input", q: "Как называется число дуг, выходящих из вершины орграфа (два слова без пробела)?", answer: "полустепеньвыхода", explain: "Это полустепень выхода." }
